import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, consider the alternating-coefficient factorial sum defined as follows. Fix integers {start} (start index), {step} (step size), {max_index} (maximum index), and {period} (period length), together with a periodic integer coefficient pattern [coeffs] of length {period}. Define K = sum over all k >= 0 with s_k = {start} + k*{step} <= {max_index} of a_{k mod {period}} · (s_k)!, where a_r are the entries of [coeffs] in order. Let (f_1, f_2, ..., f_j) be the factorial-base expansion of K (so K = sum_{i=1}^{j} i!·f_i with 0 ≤ f_i ≤ i and f_j > 0). Compute the alternating digit sum S = f_1 − f_2 + f_3 − f_4 + ... + (−1)^{j+1} f_j.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Randomly generate parameters for the generalized factorial-base problem.
# We aim for many terms, mixed signs, and at least one coefficient with magnitude >= 2,
# plus a positive last term to ensure K > 0.
while True:
    max_index = rng.randint(600, 1600)
    step = rng.randint(8, 40)
    start = rng.randint(12, 150)
    if start > max_index:
        continue
    K = (max_index - start) // step  # number of steps minus one
    terms_count = K + 1
    if terms_count < 12 or terms_count > 120:
        # ensure enough terms for non-trivial behavior and computational feasibility
        continue
    period = rng.randint(3, 6)
    # Generate a periodic coefficient sequence with mixed signs and at least one |coeff| >= 2
    def make_seq():
        seq = [rng.choice([-3, -2, -1, 1, 2, 3]) for _ in range(period)]
        neg_count = sum(1 for x in seq if x < 0)
        pos_count = sum(1 for x in seq if x > 0)
        has_ge2 = any(abs(x) >= 2 for x in seq)
        if neg_count < 2 or pos_count < 1 or not has_ge2:
            return None
        return seq
    seq = None
    for _ in range(100):
        seq = make_seq()
        if seq is not None:
            break
    if seq is None:
        # Retry the entire parameter selection
        continue
    # Ensure the last coefficient in the progression is positive for guaranteed K > 0.
    last_coeff_index = K % period
    if seq[last_coeff_index] <= 0:
        seq[last_coeff_index] = rng.choice([1, 2, 3])
        # Maintain at least two negatives overall.
        if sum(1 for x in seq if x < 0) < 2:
            candidates = [i for i in range(period) if i != last_coeff_index]
            if not candidates:
                continue
            flip_idx = rng.choice(candidates)
            seq[flip_idx] = -rng.choice([1, 2, 3])
    # Return a valid assignment.
    return {'start': start, 'step': step, 'max_index': max_index, 'period': period, 'coeffs': seq}

    def verifier(assign):
# Verify domain constraints; compute factorial-base digits via carry algorithm; enforce difficulty.
# Return (True, answer) or (False, None) on invalid input.
# Extract parameters
try:
    start = int(assign['start'])
    step = int(assign['step'])
    max_index = int(assign['max_index'])
    period = int(assign['period'])
    coeffs = list(assign['coeffs'])
except Exception:
    # Missing or malformed parameters
    return (False, None)  # invalid assignment
# Basic validity checks
if not (2 <= step and 1 <= start < max_index):
    return (False, None)  # invalid assignment
if not (3 <= period == len(coeffs)):
    return (False, None)
if any(x == 0 for x in coeffs):
    return (False, None)
# Build coefficient map for i! terms in the arithmetic progression
c = {}
k = 0
terms_count = 0
last_i = None
while True:
    i = start + k * step
    if i > max_index:
        break
    c[i] = int(coeffs[k % period])
    terms_count += 1
    last_i = i
    k += 1
if terms_count < 12 or last_i is None:
    return (False, None)
# Ensure both signs in pattern and positive last coefficient for positivity of K
if sum(1 for x in coeffs if x < 0) < 2 or sum(1 for x in coeffs if x > 0) < 1:
    return (False, None)
if c[last_i] <= 0:
    return (False, None)
# Factorial-base digit computation via mixed-radix carries
digits = []  # f_1, f_2, ...
t = 0  # carry to next radix (i+1)
carry_events = 0
# Process up to max_index
for i in range(1, max_index + 1):
    s = t + (c.get(i, 0))
    # Canonical remainder in [0, i]
    d = s % (i + 1)
    q = (s - d) // (i + 1)
    digits.append(d)
    if q != 0:
        carry_events += 1
    t = q
# Continue carrying beyond max_index until carry vanishes
while t != 0:
    i = len(digits) + 1
    s = t
    d = s % (i + 1)
    q = (s - d) // (i + 1)
    digits.append(d)
    if q != 0:
        carry_events += 1
    t = q
# Determine j as the largest index with a positive digit
j = 0
for idx in range(len(digits), 0, -1):
    if digits[idx - 1] > 0:
        j = idx
        break
if j == 0:
    # K should be positive; this indicates invalid parameters
    return (False, None)
# Difficulty guard: ensure at least two carry/borrow events occurred
if carry_events < 2:
    return (False, None)
# Compute alternating digit sum S
S = 0
for i in range(1, j + 1):
    S += (digits[i - 1] if i % 2 == 1 else -digits[i - 1])
return (True, S)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

